badExample:
items.forEach(async (item) => {
    await saveToDb(item);
});
console.log("Done"); // Prints before saveToDb finishes!

fixedExample:
for (const item of items) {
    await saveToDb(item);
}
console.log("Done"); // Waits properly

badExample:
class Counter {
    constructor() { this.count = 0; }
    inc() { this.count++; }
}
const c = new Counter();
setTimeout(c.inc, 100); // this is undefined!

fixedExample:
class Counter {
    constructor() { this.count = 0; }
    inc = () => { this.count++; }
}
const c = new Counter();
setTimeout(c.inc, 100);

badExample:
function isZero(val) {
    return val == 0; // Returns true for "", false, [], and nullish strings!
}

for (var i = 0; i < 3; i++) {
    setTimeout(() => console.log(i), 10); // Prints 3, 3, 3
}

fixedExample:
for (let i = 0; i < 3; i++) {
    setTimeout(() => console.log(i), 10); // Prints 0, 1, 2
}

badExample:
function parseData(str) {
    return JSON.parse(str); // Crashes if str is invalid!
}

fixedExample:
function parseData(str, fallback = {}) {
    try {
        return JSON.parse(str);
    } catch {
        return fallback;
    }
}

badExample:
function addConfig(cfg) {
    cfg.active = true; // Mutates caller's original config!
    return cfg;
}

fixedExample:
function addConfig(cfg) {
    return { ...cfg, active: true }; // Pure clone with new property
}

badExample:
async function fetchData() {
    throw new Error("Network failed");
}
fetchData(); // Crash: UnhandledPromiseRejection!

fixedExample:
async function fetchData() {
    throw new Error("Network failed");
}
fetchData().catch((err) => {
    console.error("Handled failure:", err.message);
});
